import ctypes, math

def f(x):
    return ctypes.c_float(x).value

def hsl_adjust(r,g,b,factor):
    r=f(r);g=f(g);b=f(b);factor=f(factor)
    mx=max(r,g,b); mn=min(r,g,b)
    l=f((mx+mn)/2.0)
    if mx==mn:
        h=f(0.0); s=f(0.0)
    else:
        d=f(mx-mn)
        if l>0.5:
            s=f(d/(2.0-mx-mn))
        else:
            s=f(d/(mx+mn))
        if mx==r:
            h0=(g-b)/d + (6.0 if g<b else 0.0)
        elif mx==g:
            h0=(b-r)/d + 2.0
        else:
            h0=(r-g)/d + 4.0
        h=f(h0/6.0)
    s=f(s*factor)
    if s<0.0: s=f(0.0)
    if s>1.0: s=f(1.0)
    if s==0.0:
        return f(l),f(l),f(l)
    q=f(l*(1.0+s) if l<0.5 else l+s-l*s)
    p=f(2.0*l-q)
    def hue_to_rgb(p,q,t):
        p=f(p);q=f(q);t=f(t)
        if t<0.0: t=f(t+1.0)
        if t>1.0: t=f(t-1.0)
        if t<1.0/6.0:
            return f(p+(q-p)*6.0*t)
        if t<0.5:
            return q
        if t<2.0/3.0:
            return f(p+(q-p)*(2.0/3.0-t)*6.0)
        return p
    return hue_to_rgb(p,q,f(h+1.0/3.0)), hue_to_rgb(p,q,h), hue_to_rgb(p,q,f(h-1.0/3.0))

for args in [ (0.5,0.6,0.7,1.5),(1,0,0,2),(1,0,0,0),(0.2,0.4,0.6,2),(0.2,0.4,0.6,10),(0.2,0.4,0.6,0.5) ]:
    print(args, hsl_adjust(*args))
