use std::process::Command;

const PRECISION: usize = 6;

#[derive(Clone, Copy)]
struct Rgb {
    r: f32,
    g: f32,
    b: f32,
}

#[derive(Clone, Copy)]
struct Hsl {
    h: f32,
    s: f32,
    l: f32,
}

fn clamp01(value: f32) -> f32 {
    if value < 0.0 {
        0.0
    } else if value > 1.0 {
        1.0
    } else {
        value
    }
}

fn rgb_to_hsl(rgb: Rgb) -> Hsl {
    let max = rgb.r.max(rgb.g.max(rgb.b));
    let min = rgb.r.min(rgb.g.min(rgb.b));
    let lightness = (max + min) / 2.0;

    if max == min {
        return Hsl { h: 0.0, s: 0.0, l: lightness };
    }

    let delta = max - min;
    let saturation = if lightness > 0.5 {
        delta / (2.0 - max - min)
    } else {
        delta / (max + min)
    };

    let mut hue = if rgb.r == max {
        ((rgb.g - rgb.b) / delta) + if rgb.b > rgb.g { 6.0 } else { 0.0 }
    } else if rgb.g == max {
        ((rgb.b - rgb.r) / delta) + 2.0
    } else {
        ((rgb.r - rgb.g) / delta) + 4.0
    };

    hue /= 6.0;
    hue *= 360.0;

    Hsl { h: hue, s: saturation, l: lightness }
}

fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }
    if t < 1.0 / 6.0 {
        p + (q - p) * 6.0 * t
    } else if t < 0.5 {
        q
    } else if t < 2.0 / 3.0 {
        p + (q - p) * (2.0 / 3.0 - t) * 6.0
    } else {
        p
    }
}

fn hsl_to_rgb(hsl: Hsl) -> Rgb {
    let hue = hsl.h / 360.0;
    if hsl.s == 0.0 {
        return Rgb { r: hsl.l, g: hsl.l, b: hsl.l };
    }

    let q = if hsl.l < 0.5 {
        hsl.l * (1.0 + hsl.s)
    } else {
        hsl.l + hsl.s - hsl.l * hsl.s
    };
    let p = 2.0 * hsl.l - q;

    Rgb {
        r: hue_to_rgb(p, q, hue + 1.0 / 3.0),
        g: hue_to_rgb(p, q, hue),
        b: hue_to_rgb(p, q, hue - 1.0 / 3.0),
    }
}

fn adjust_saturation(rgb: Rgb, factor: f32) -> Rgb {
    let mut hsl = rgb_to_hsl(rgb);
    hsl.s = clamp01(hsl.s * factor);
    hsl_to_rgb(hsl)
}

fn trim_trailing_zeros(mut s: String) -> String {
    if let Some(dot_index) = s.find('.') {
        while s.ends_with('0') {
            s.pop();
        }
        if s.len() == dot_index + 1 {
            s.pop();
        }
    }
    s
}

fn scientific_to_fixed(digits: &str, exponent: i32) -> String {
    let point = exponent + 1;
    let mut result = String::new();
    if point <= 0 {
