const PRECISION: usize = 6;

pub fn format_cpp_float(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    if value == 0.0 {
        return if value.is_sign_negative() {
            String::from("-0")
        } else {
            String::from("0")
        };
    }

    let negative = value.is_sign_negative();
    let scientific = format!("{:.*e}", PRECISION - 1, f64::from(value.abs()));
    let (mantissa_raw, exponent_raw) = scientific.split_once('e').unwrap();
    let exponent: i32 = exponent_raw.parse().unwrap();

    if exponent < -4 || exponent >= PRECISION as i32 {
        let mantissa = trim_trailing_zeros(mantissa_raw.to_string());
        let mut output = String::new();

        if negative {
            output.push('-');
        }

        output.push_str(&mantissa);
        output.push('e');
        output.push(if exponent < 0 { '-' } else { '+' });

        let exponent_abs = exponent.abs();
        if exponent_abs < 10 {
            output.push('0');
        }
        output.push_str(&exponent_abs.to_string());

        return output;
    }

    let digits: String = mantissa_raw.chars().filter(|&ch| ch != '.').collect();
    let mut output = scientific_to_fixed(&digits, exponent);

    if negative {
        output.insert(0, '-');
    }

    output
}

fn scientific_to_fixed(digits: &str, exponent: i32) -> String {
    let point = exponent + 1;
    let mut output = String::new();

    if point <= 0 {
        output.push_str("0.");
        for _ in 0..((-point) as usize) {
            output.push('0');
        }
        output.push_str(digits);
    } else {
        let point = point as usize;
        if point >= digits.len() {
            output.push_str(digits);
            for _ in 0..(point - digits.len()) {
                output.push('0');
            }
        } else {
            output.push_str(&digits[..point]);
            output.push('.');
            output.push_str(&digits[point..]);
        }
    }

    trim_trailing_zeros(output)
}

fn trim_trailing_zeros(mut value: String) -> String {
    if let Some(dot_index) = value.find('.') {
        while value.ends_with('0') {
            value.pop();
        }
        if value.len() == dot_index + 1 {
            value.pop();
        }
    }
    value
}

#[cfg(test)]
mod tests {
    use super::format_cpp_float;

    #[test]
    fn matches_cpp_default_float_formatting() {
        assert_eq!(format_cpp_float(0.0), "0");
        assert_eq!(format_cpp_float(-0.0), "-0");
        assert_eq!(format_cpp_float(0.45), "0.45");
        assert_eq!(format_cpp_float(3.5762787e-7), "3.57628e-07");
        assert_eq!(format_cpp_float(999999.5), "1e+06");
        assert_eq!(format_cpp_float(999999.4), "999999");
        assert_eq!(format_cpp_float(0.00009999995), "9.99999e-05");
