use super::{HSL, RGB};

pub struct ColorConverter;

impl ColorConverter {
    pub fn adjust_saturation(rgb: RGB, factor: f32) -> RGB {
        let mut hsl = Self::rgb_to_hsl(rgb);
        hsl.s = clamp(hsl.s * factor, 0.0, 1.0);
        Self::hsl_to_rgb(hsl)
    }

    fn rgb_to_hsl(rgb: RGB) -> HSL {
        let max = rgb.r.max(rgb.g.max(rgb.b));
        let min = rgb.r.min(rgb.g.min(rgb.b));
        let lightness = (max + min) / 2.0;

        if max == min {
            return HSL::new(0.0, 0.0, lightness);
        }

        let delta = max - min;
        let saturation = if lightness > 0.5 {
            delta / (2.0 - max - min)
        } else {
            delta / (max + min)
        };

        let mut hue = if rgb.r == max {
            ((rgb.g - rgb.b) / delta) + if rgb.b > rgb.g { 6.0 } else { 0.0 }
        } else if rgb.g == max {
            ((rgb.b - rgb.r) / delta) + 2.0
        } else {
            ((rgb.r - rgb.g) / delta) + 4.0
        };

        hue /= 6.0;
        hue *= 360.0;

        HSL::new(hue, saturation, lightness)
    }

    fn hsl_to_rgb(hsl: HSL) -> RGB {
        let hue = hsl.h / 360.0;

        if hsl.s == 0.0 {
            return RGB::new(hsl.l, hsl.l, hsl.l);
        }

        let q = if hsl.l < 0.5 {
            hsl.l * (1.0 + hsl.s)
        } else {
            hsl.l + hsl.s - hsl.l * hsl.s
        };
        let p = (2.0 * hsl.l) - q;

        RGB::new(
            hue_to_rgb(p, q, hue + (1.0 / 3.0)),
            hue_to_rgb(p, q, hue),
            hue_to_rgb(p, q, hue - (1.0 / 3.0)),
        )
    }
}

fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }

    if t < (1.0 / 6.0) {
        p + ((q - p) * 6.0 * t)
    } else if t < 0.5 {
        q
    } else if t < (2.0 / 3.0) {
        p + ((q - p) * ((2.0 / 3.0) - t) * 6.0)
    } else {
        p
    }
}

fn clamp(value: f32, min: f32, max: f32) -> f32 {
    if value < min {
        min
    } else if value > max {
        max
    } else {
        value
    }
}

#[cfg(test)]
