    use super::{ColorConverter, RGB};

    #[test]
    fn matches_reference_examples() {
        let result = ColorConverter::adjust_saturation(RGB::new(0.5, 0.6, 0.7), 1.5);
        assert_eq!(result, RGB::new(0.45000005, 0.6000001, 0.75));

