        .map_err(|err| format!("rust execution failed: {err}"))?;

    let expected_stdout = String::from_utf8(expected.stdout).map_err(|err| err.to_string())?;
    let actual_stdout = String::from_utf8(actual.stdout).map_err(|err| err.to_string())?;

    if expected_stdout != actual_stdout {
        return Err(format!(
            "mismatch for {:?}: expected {:?}, got {:?}",
            args, expected_stdout, actual_stdout
        ));
    }

    Ok(())
}

fn main() {
