        let g = formatting::format_cpp_float(next(&mut seed));
        let b = formatting::format_cpp_float(next(&mut seed));
        let factor = formatting::format_cpp_float((next(&mut seed) * 4.0) - 1.0);
        check_case(&[r, g, b, factor]).unwrap();
